   106→// runExplainDefault explains the current session.
   107→func runExplainDefault(w io.Writer, noPager bool) error {
   108→	// Read current session
   109→	currentSessionID, err := paths.ReadCurrentSession()
   110→	if err != nil {
   111→		return fmt.Errorf("failed to read current session: %w", err)
   112→	}
   113→
   114→	if currentSessionID == "" {
   115→		return errors.New("no active session. Use --session or --commit to specify what to explain")
