   121→// runExplainSession explains a specific session.
   122→func runExplainSession(w io.Writer, sessionID string, noPager bool) error {
   123→	strat := GetStrategy()
   124→
   125→	// Get session details
   126→	session, err := strategy.GetSession(sessionID)
   127→	if err != nil {
   128→		if errors.Is(err, strategy.ErrNoSession) {
   129→			return fmt.Errorf("session not found: %s", sessionID)
   130→		}
   131→		return fmt.Errorf("failed to get session: %w", err)
   132→	}
   133→
   134→	// Get source ref (metadata branch + commit) for this session
   135→	sourceRef := strat.GetSessionMetadataRef(session.ID)
   136→
   137→	// Gather checkpoint details
   138→	checkpointDetails := gatherCheckpointDetails(strat, session)
   139→
   140→	// For strategies like shadow where active sessions may not have checkpoints,
   141→	// try to get the current session transcript directly
   142→	if len(checkpointDetails) == 0 && len(session.Checkpoints) == 0 {
   143→		checkpointDetails = gatherCurrentSessionDetails(strat, session)
   144→	}
   145→
   146→	// Format output
   147→	output := formatSessionInfo(session, sourceRef, checkpointDetails)
   148→
   149→	// Output with pager if appropriate
   150→	if noPager {
   151→		fmt.Fprint(w, output)
   152→	} else {
   153→		outputWithPager(w, output)
   154→	}
   155→
   156→	return nil
   157→}
