   356→// formatSessionInfo formats session information for display.
   357→func formatSessionInfo(session *strategy.Session, sourceRef string, checkpoints []checkpointDetail) string {
   358→	var sb strings.Builder
   359→
   360→	// Session header
   361→	sb.WriteString(fmt.Sprintf("Session: %s\n", session.ID))
   362→	sb.WriteString(fmt.Sprintf("Strategy: %s\n", session.Strategy))
   363→
   364→	if !session.StartTime.IsZero() {
   365→		sb.WriteString(fmt.Sprintf("Started: %s\n", session.StartTime.Format("2006-01-02 15:04:05")))
   366→	}
   367→
   368→	if sourceRef != "" {
   369→		sb.WriteString(fmt.Sprintf("Source Ref: %s\n", sourceRef))
   370→	}
   371→
   372→	sb.WriteString(fmt.Sprintf("Checkpoints: %d\n", len(checkpoints)))
   373→
   374→	// Checkpoint details
   375→	for _, cp := range checkpoints {
   376→		sb.WriteString("\n")
   377→
   378→		// Checkpoint header
   379→		taskMarker := ""
   380→		if cp.IsTaskCheckpoint {
   381→			taskMarker = " [Task]"
   382→		}
   383→		sb.WriteString(fmt.Sprintf("─── Checkpoint %d [%s] %s%s ───\n",
   384→			cp.Index, cp.ShortID, cp.Timestamp.Format("2006-01-02 15:04"), taskMarker))
   385→		sb.WriteString("\n")
   386→
   387→		// Display all interactions in this checkpoint
   388→		for i, inter := range cp.Interactions {
   389→			// For multiple interactions, add a sub-header
   390→			if len(cp.Interactions) > 1 {
   391→				sb.WriteString(fmt.Sprintf("### Interaction %d\n\n", i+1))
   392→			}
   393→
   394→			// Prompt section
   395→			if inter.Prompt != "" {
   396→				sb.WriteString("## Prompt\n\n")
   397→				sb.WriteString(inter.Prompt)
   398→				sb.WriteString("\n\n")
   399→			}
   400→
   401→			// Response section
   402→			if len(inter.Responses) > 0 {
   403→				sb.WriteString("## Responses\n\n")
   404→				sb.WriteString(strings.Join(inter.Responses, "\n\n"))
   405→				sb.WriteString("\n\n")
   406→			}
   407→
   408→			// Files modified for this interaction
   409→			if len(inter.Files) > 0 {
   410→				sb.WriteString(fmt.Sprintf("Files Modified (%d):\n", len(inter.Files)))
   411→				for _, file := range inter.Files {
   412→					sb.WriteString(fmt.Sprintf("  - %s\n", file))
   413→				}
   414→				sb.WriteString("\n")
   415→			}
   416→		}
   417→
   418→		// If no interactions, show message and/or files
   419→		if len(cp.Interactions) == 0 {
   420→			// Show commit message as summary when no transcript available
   421→			if cp.Message != "" {
   422→				sb.WriteString(cp.Message)
   423→				sb.WriteString("\n\n")
   424→			}
   425→			// Show aggregate files if available
   426→			if len(cp.Files) > 0 {
   427→				sb.WriteString(fmt.Sprintf("Files Modified (%d):\n", len(cp.Files)))
   428→				for _, file := range cp.Files {
   429→					sb.WriteString(fmt.Sprintf("  - %s\n", file))
   430→				}
   431→			}
   432→		}
   433→	}
   434→
   435→	return sb.String()
   436→}
